// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;

    function setUp() public { c = new airdrop(); }

    // fuzzed params: from address, uint v, and a boolean that chooses whether the callee should revert
    function testFuzz_property(address from, uint256 v, bool shouldRevert) public {
        // keep from non-zero to be a realistic caller value; but not strictly necessary
        vm.assume(from != address(0));

        // deploy a helper that implements transferFrom(address,address,uint256)
        // it will either revert or succeed depending on shouldRevert
        CalleeHelper helper = new CalleeHelper(shouldRevert);

        // prepare a non-empty _tos array with exactly one recipient to keep observation simple
        address[] memory tos = new address[](1);
        tos[0] = address(0xBEEF);

        // Call c.transfer through try/catch to observe whether it reverts (correct contract should revert when callee reverts)
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees: if the helper's transferFrom reverts (shouldRevert==true), c.transfer always reverts (ok==false).
        // The mutant that ignores the success flag will return true even when helper reverts, so this assertion will fail on that mutant for some inputs.
        if (shouldRevert) {
            assertTrue(!ok);
        } else {
            // when helper does not revert, c.transfer should succeed
            assertTrue(ok);
        }
    }
}

// Helper that either reverts or returns success for the selector transferFrom(address,address,uint256)
contract CalleeHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // match the selector: transferFrom(address,address,uint256)
    function transferFrom(address /*from*/, address /*to*/, uint256 /*v*/) external returns (bool) {
        if (shouldRevert) {
            revert("forced revert");
        }
        return true;
    }
}
